 "content": "def transform(grid):
    """Extend each isolated marker using the horizontal color sequence containing it."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sequences = []
    # Contiguous nonzero horizontal runs of length >= 2 are the reference sequences.
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start >= 2:
                sequences.append((row[start:c], r, start))
    reference_rows = {r for _, r, _ in sequences}
    # Each singleton in a non-reference row receives the sequence that contains its color,
    # positioned so the matching color remains at the marker's original coordinate.
    for r, row in enumerate(grid):
        if r in reference_rows:
            continue
        cells = [c for c, v in enumerate(row) if v != 0]
        if len(cells) != 1:
            continue
        c = cells[0]
        color = row[c]
        match = next((seq for seq, _, _ in sequences if color in seq), None)
        if match is None:
            continue
        anchor = match.index(color)
        left = c - anchor
        for i, value in enumerate(match):
            cc = left + i
            if 0 <= cc < w:
                out[r][cc] = value
    return out

if __name__ == '__main__':
    import sys, json
    print(json.dumps(transform(json.loads(sys.stdin.read()))))
